# Return linework only: never pass a polygon fill through this function.
boundary_line_sf <- function(g) {
  g <- g[!sf::st_is_empty(g)]
  if (!length(g)) return(sf::st_sf(geometry = sf::st_sfc(crs = 4326)))
  if (any(as.character(sf::st_geometry_type(g)) == "GEOMETRYCOLLECTION"))
    g <- suppressWarnings(sf::st_collection_extract(g, "LINESTRING"))
  # Union/merge avoids duplicate solid strokes and dash restarts at source nodes.
  g <- sf::st_union(g)
  if (any(as.character(sf::st_geometry_type(g)) == "MULTILINESTRING"))
    g <- sf::st_line_merge(g)
  sf::st_sf(geometry = sf::st_transform(g, 4326))
}

prepare_boundary_display <- function(zones, regions, neighbors, africa) {
  disputed <- load_supplied_disputed_lines()
  metric_lines <- sf::st_transform(sf::st_geometry(disputed), boundary_display_crs)
  corridor <- sf::st_union(sf::st_buffer(metric_lines,
                                        dist = boundary_display_tolerance_m))
  # Identify true ends of the supplied line network, not intermediate nodes.
  # Branch junctions and closed rings are not terminal points.
  network <- sf::st_union(metric_lines)
  if (any(as.character(sf::st_geometry_type(network)) == "MULTILINESTRING"))
    network <- sf::st_line_merge(network)
  chains <- suppressWarnings(sf::st_cast(network, "LINESTRING"))
  end_xy <- do.call(rbind, lapply(chains, function(g) {
    xy <- sf::st_coordinates(g)[, 1:2, drop = FALSE]
    xy[c(1L, nrow(xy)), , drop = FALSE]
  }))
  end_key <- paste(round(end_xy[, 1], 2), round(end_xy[, 2], 2), sep = ":")
  is_terminal <- !duplicated(end_key) & !duplicated(end_key, fromLast = TRUE)
  end_xy <- end_xy[is_terminal, , drop = FALSE]
  terminals <- sf::st_sfc(lapply(seq_len(nrow(end_xy)), function(i)
    sf::st_point(end_xy[i, ])), crs = boundary_display_crs)
  corridor_edge <- sf::st_boundary(corridor)

  # Restore continuity at mask-created cuts. Only the solid display line is
  # connected to the unchanged UN terminal. This is a short cartographic
  # transition between differently generalised datasets, not a new boundary.
  reconnect_solid_ends <- function(g, eligible) {
    if (!length(g) || !length(terminals)) return(g)
    ends <- do.call(rbind, lapply(g, function(line) {
      xy <- sf::st_coordinates(line)[, 1:2, drop = FALSE]
      xy[c(1L, nrow(xy)), , drop = FALSE]
    }))
    points <- sf::st_sfc(lapply(seq_len(nrow(ends)), function(i)
      sf::st_point(ends[i, ])), crs = boundary_display_crs)
    nearest <- sf::st_nearest_feature(points, terminals)
    distance <- as.numeric(sf::st_distance(points, terminals[nearest], by_element = TRUE))
    on_cut <- as.numeric(sf::st_distance(points, corridor_edge)) <= 1
    repair <- rep(eligible, each = 2L) & on_cut &
      distance <= 2 * boundary_display_tolerance_m
    coords <- lapply(seq_along(g), function(i) {
      xy <- sf::st_coordinates(g[[i]])[, 1:2, drop = FALSE]
      left <- 2L * i - 1L; right <- 2L * i
      if (repair[left]) xy <- rbind(end_xy[nearest[left], ], xy)
      if (repair[right]) xy <- rbind(xy, end_xy[nearest[right], ])
      sf::st_linestring(xy)
    })
    sf::st_sfc(coords, crs = boundary_display_crs)
  }

  # Extract polygon edges before map cropping. Keep original ring identity
  # through the difference so a small offshore island cannot snap to a border.
  solid_edges <- function(polygons, extent = NULL) {
    if (is.null(polygons) || !nrow(polygons))
      return(sf::st_sf(geometry = sf::st_sfc(crs = 4326)))
    g <- sf::st_geometry(sf::st_transform(polygons, boundary_display_crs))
    g <- sf::st_boundary(sf::st_make_valid(g))
    g <- sf::st_cast(sf::st_cast(g, "MULTILINESTRING"), "LINESTRING")
    rings <- sf::st_sf(
      eligible = as.numeric(sf::st_length(g)) > 4 * boundary_display_tolerance_m,
      geometry = g
    )
    cut <- suppressWarnings(sf::st_difference(rings, corridor))
    cut <- cut[!sf::st_is_empty(cut), , drop = FALSE]
    cut <- suppressWarnings(sf::st_cast(
      sf::st_cast(cut, "MULTILINESTRING"), "LINESTRING"))
    g <- reconnect_solid_ends(sf::st_geometry(cut), cut$eligible)
    if (!is.null(extent)) {
      box <- sf::st_transform(sf::st_as_sfc(extent), boundary_display_crs)
      g <- suppressWarnings(sf::st_intersection(g, box))
    }
    boundary_line_sf(g)
  }

  eth_polygon <- sf::st_union(sf::st_geometry(sf::st_transform(
    sf::st_make_valid(regions), boundary_display_crs)))
  national_edge <- sf::st_boundary(eth_polygon)
  national_display <- solid_edges(sf::st_sf(geometry = eth_polygon))
  internal_edges <- function(polygons) {
    g <- sf::st_boundary(sf::st_geometry(sf::st_transform(
      sf::st_make_valid(polygons), boundary_display_crs)))
    # Remove only the duplicate exterior edge; do not erase district borders
    # throughout the much wider disputed-line matching corridor.
    g <- suppressWarnings(sf::st_difference(g, sf::st_buffer(national_edge, 100)))
    boundary_line_sf(g)
  }
  region_internal <- internal_edges(regions)
  region_display <- boundary_line_sf(c(sf::st_geometry(region_internal),
                                       sf::st_geometry(national_display)))
  clip_disputed <- function(extent, keep = rep(TRUE, length(metric_lines))) {
    box <- sf::st_transform(sf::st_as_sfc(extent), boundary_display_crs)
    g <- suppressWarnings(sf::st_intersection(metric_lines[keep], box))
    boundary_line_sf(g)
  }
  eth_extent <- sf::st_bbox(sf::st_transform(regions, 4326))
  # Include a modest context margin; adding dashed layers must not expand
  # Ethiopia maps to Egypt or the full Sudan-South Sudan boundary.
  main_extent <- eth_extent
  main_extent[c("xmin", "ymin")] <- main_extent[c("xmin", "ymin")] - 0.15
  main_extent[c("xmax", "ymax")] <- main_extent[c("xmax", "ymax")] + 0.15
  if (exists("neighboring_countries_sf", inherits = TRUE) &&
      !is.null(neighboring_countries_sf) && nrow(neighboring_countries_sf)) {
    b <- sf::st_bbox(sf::st_transform(neighboring_countries_sf, 4326))
    main_extent[c("xmin", "ymin")] <- pmin(main_extent[c("xmin", "ymin")], b[c("xmin", "ymin")])
    main_extent[c("xmax", "ymax")] <- pmax(main_extent[c("xmax", "ymax")], b[c("xmax", "ymax")])
  }
  # Southern Ilemi baseline shown in the supplied FAO maps. GADM follows
  # the northern outline here, so masking that outline alone omits the solid
  # horizontal line. Derive the baseline from the supplied Ilemi endpoints;
  # do not move the dashed line or change any country/analysis polygons.
  ilemi <- sf::st_union(sf::st_geometry(
    disputed[disputed$source == "Ilemi", ]))
  if (inherits(ilemi, "sfc_MULTILINESTRING")) ilemi <- sf::st_line_merge(ilemi)
  ilemi_xy <- sf::st_coordinates(ilemi)[, 1:2, drop = FALSE]
  ilemi_ends <- ilemi_xy[c(1L, nrow(ilemi_xy)), , drop = FALSE]
  if (abs(diff(ilemi_ends[, 2])) > 0.01)
    stop("Unexpected Ilemi endpoints: inspect the supplied reference line.")
  baseline_xy <- cbind(
    seq(min(ilemi_ends[, 1]), max(ilemi_ends[, 1]), length.out = 101L),
    rep(mean(ilemi_ends[, 2]), 101L))
  ilemi_baseline <- sf::st_sfc(sf::st_linestring(baseline_xy), crs = 4326)
  baseline_metric <- sf::st_transform(ilemi_baseline, boundary_display_crs)

  # Use the SAME displayed country polygons for clipping. A padded bounding
  # box can otherwise leave line ends outside the grey background, especially
  # after spherical cropping/reprojection. A 5 cm tolerance retains strokes
  # exactly on a polygon edge despite floating-point roundoff.
  context_footprint <- eth_polygon
  if (exists("neighboring_countries_sf", inherits = TRUE) &&
      !is.null(neighboring_countries_sf) && nrow(neighboring_countries_sf)) {
    context_footprint <- sf::st_union(c(eth_polygon,
      sf::st_geometry(sf::st_make_valid(sf::st_transform(
        neighboring_countries_sf, boundary_display_crs)))))
  }
  clip_to_context <- function(lines) {
    geometry <- sf::st_transform(sf::st_geometry(lines), boundary_display_crs)
    geometry <- suppressWarnings(sf::st_intersection(geometry,
      sf::st_buffer(context_footprint, 0.05)))
    boundary_line_sf(geometry)
  }
  neighbor_lines <- solid_edges(neighbors, main_extent)
  neighbor_lines <- boundary_line_sf(c(
    sf::st_transform(sf::st_geometry(neighbor_lines), boundary_display_crs),
    baseline_metric))
  africa_lines <- solid_edges(africa)
  africa_lines <- boundary_line_sf(c(
    sf::st_transform(sf::st_geometry(africa_lines), boundary_display_crs),
    baseline_metric))

  # Transparent maps omit neighboring countries; show only the supplied
  # Ethiopia-Somalia segment there, without floating third-country borders.
  transparent_extent <- eth_extent
  transparent_extent[c("xmin", "ymin")] <- transparent_extent[c("xmin", "ymin")] - 0.15
  transparent_extent[c("xmax", "ymax")] <- transparent_extent[c("xmax", "ymax")] + 0.15
  cat("Preparing solid/dashed boundary display from 19 supplied line features...\n")
  list(
    districts = internal_edges(zones),
    regions = region_display,
    neighbors = clip_to_context(neighbor_lines),
    africa = africa_lines,
    ethiopia = national_display,
    main_dashed = clip_to_context(clip_disputed(main_extent)),
    main_footprint = sf::st_sf(geometry = context_footprint),
    ilemi_baseline = sf::st_sf(geometry = ilemi_baseline),
    transparent_dashed = clip_disputed(transparent_extent, disputed$source == "Somalia"),
    africa_dashed = boundary_line_sf(metric_lines)
  )
}

add_disputed_boundary_caption <- function(p) {
  previous <- p$labels$caption
  if (is.null(previous)) previous <- character(0)
  text <- paste(c(previous, boundary_disclaimer), collapse = "\n")
  p + ggplot2::labs(caption = paste(strwrap(text, width = 105), collapse = "\n"))
}

library(ggplot2)
library(dplyr)
library(readr)
library(sf)
library(geodata)
library(viridis)
library(gridExtra)
library(grid)
library(gtable)
library(readxl)
library(ggspatial)
library(cowplot)
library(ggpattern)

# Get Ethiopian administrative boundaries at zone level (level 2)
# Ethiopia GADM data goes to level 2 (Zones), similar to Nigeria's LGAs
ethiopia_zones <- gadm(country = "ETH", level = 3, path = tempdir())
ethiopia_zones_sf <- st_as_sf(ethiopia_zones)


# Load the updated local admin1 region boundaries for context
ethiopia_regions <- sf::st_read("Data/eth_admin1/eth_admin1.shp", quiet = TRUE)
ethiopia_regions_sf <- st_as_sf(ethiopia_regions)

# Load neighboring countries for geographic context
cat("Loading neighboring countries for geographic context...\n")
neighbor_countries <- c("Sudan" = "SDN", "South Sudan" = "SSD", "Kenya" = "KEN", 
                       "Somalia" = "SOM", "Djibouti" = "DJI", "Eritrea" = "ERI", "Uganda" = "UGA")

neighboring_countries_list <- list()
for(i in 1:length(neighbor_countries)) {
  country_name <- names(neighbor_countries)[i]
  country_code <- neighbor_countries[i]
  
  tryCatch({
    country_data <- gadm(country = country_code, level = 0, path = tempdir())
    country_sf <- st_as_sf(country_data)
    neighboring_countries_list[[country_name]] <- country_sf
    cat("Loaded", country_name, "(", country_code, ")\n")
  }, error = function(e) {
    cat("Failed to load", country_name, "(", country_code, "):", e$message, "\n")
  })
}

# Combine all neighboring countries into single sf object
if(length(neighboring_countries_list) > 0) {
  neighboring_countries_full <- do.call(rbind, neighboring_countries_list)
  
  # Validate and repair geometries to avoid intersection errors
  cat("Validating and repairing geometries...\n")
  neighboring_countries_full <- st_make_valid(neighboring_countries_full)
  ethiopia_regions_valid <- st_make_valid(ethiopia_regions_sf)
  
  # Create a buffer around Ethiopia to crop neighboring countries to border regions only
  ethiopia_buffer <- st_buffer(st_union(ethiopia_regions_valid), dist = 1.5)  # ~150km buffer
  ethiopia_buffer <- st_make_valid(ethiopia_buffer)
  
  # Use st_crop instead of st_intersection for more robust clipping
  tryCatch({
    neighboring_countries_sf <- st_crop(neighboring_countries_full, ethiopia_buffer)
    cat("Successfully loaded and cropped", nrow(neighboring_countries_sf), "neighboring country border regions\n")
  }, error = function(e) {
    cat("st_crop failed, trying alternative approach:", e$message, "\n")
    # Fallback: use a simpler bbox-based crop
    ethiopia_bbox <- st_bbox(ethiopia_buffer)
    neighboring_countries_sf <<- st_crop(neighboring_countries_full, ethiopia_bbox)
    cat("Successfully loaded and cropped using bbox approach\n")
  })
  
} else {
  neighboring_countries_sf <- NULL
  cat("No neighboring countries loaded\n")
}

# Load continental Africa for inset map
cat("Loading continental Africa for inset map...\n")
africa_countries_sf <- NULL
ethiopia_country_sf <- NULL
tryCatch({
  # Get all African countries
  africa_iso3 <- c("DZA", "AGO", "BEN", "BWA", "BFA", "BDI", "CMR", "CPV", "CAF", 
                   "TCD", "COM", "COG", "COD", "CIV", "DJI", "EGY", "GNQ", "ERI", 
                   "ETH", "ESH", "GAB", "GMB", "GHA", "GIN", "GNB", "KEN", "LSO", "LBR", 
                   "LBY", "MDG", "MWI", "MLI", "MRT", "MUS", "MAR", "MOZ", "NAM", 
                   "NER", "NGA", "RWA", "STP", "SEN", "SYC", "SLE", "SOM", "ZAF", 
                   "SSD", "SDN", "SWZ", "TZA", "TGO", "TUN", "UGA", "ZMB", "ZWE")
  
  africa_list <- list()
  for(country_code in africa_iso3) {
    tryCatch({
      country_data <- gadm(country = country_code, level = 0, path = tempdir())
      africa_list[[country_code]] <- st_as_sf(country_data)
    }, error = function(e) {
      # Silently skip countries that fail to load
    })
  }
  
  if(length(africa_list) > 0) {
    africa_countries_sf <- do.call(rbind, africa_list)
