# Function to load and process a single projection file
load_projection_file <- function(file_path) {
  tryCatch({
    cat("Reading projection:", basename(file_path), "\n")
    flush.console()
    data <- read.csv(file_path, stringsAsFactors = FALSE,
                     colClasses = c(Latitude = "numeric", Longitude = "numeric",
                                    value = "numeric", variable = "character"))
    # Add model identifier
    data$model_id <- basename(file_path)
    return(data)
  }, error = function(e) {
    cat("Error loading", file_path, ":", e$message, "\n")
    stop("Projection load failed; no model was silently omitted.", call. = FALSE)
  })
}

