}

# Function to create choropleth map (matching Nigerian version exactly)
create_choropleth <- function(lga_data, title_suffix, data_type = "mean", add_bovine = FALSE, show_uncertainty = TRUE, add_inset = FALSE) {
  
  # Handle the different data types
  if(data_type == "mean") {
    fill_column <- "mean_prevalence"
  } else if(data_type == "lower") {
    fill_column <- "lower_prevalence"  
  } else if(data_type == "upper") {
    fill_column <- "upper_prevalence"
  } else {
    fill_column <- data_type
  }
  
  # Join zone-level prevalence back to zone polygons
  ethiopia_zones_final <- ethiopia_zones_sf %>%
    left_join(lga_data %>% st_drop_geometry() %>% dplyr::select(GID_3, all_of(fill_column)), 
              by = "GID_3")
  
  # Add uncertainty information if requested
  if(show_uncertainty) {
    ethiopia_zones_final <- ethiopia_zones_final %>%
      left_join(zone_uncertainty, by = "GID_3")
  }
  
  # Create zone-level choropleth map (matching Nigerian styling exactly)
  p <- ggplot(ethiopia_zones_final)
  
  # Add neighboring countries as background context (if available)
  if(!is.null(neighboring_countries_sf)) {
    p <- p + geom_sf(data = neighboring_countries_sf, fill = "grey95", color = NA) +
      geom_sf(data = boundary_display$neighbors, color = "grey55", lwd = 0.35,
              inherit.aes = FALSE)
  }
  
  # Add Ethiopia zones with prevalence data
  p <- p + 
    geom_sf(aes(fill = !!sym(fill_column)), color = NA) +
    geom_sf(data = boundary_display$districts, color = "black", lwd = 0.05,
            inherit.aes = FALSE) +
    geom_sf(data = boundary_display$regions, color = "black", lwd = 0.5,
            inherit.aes = FALSE)
  
  # Add high uncertainty overlay if requested
  if(show_uncertainty && "high_uncertainty" %in% names(ethiopia_zones_final)) {
    high_uncertainty_zones <- ethiopia_zones_final %>% 
      dplyr::filter(high_uncertainty == TRUE)
    
    if(nrow(high_uncertainty_zones) > 0) {
      p <- p + 
        geom_sf_pattern(
  data = high_uncertainty_zones,
  aes(pattern = "High uncertainty"),
  pattern = "crosshatch",

  fill = NA,
  colour = NA,

  pattern_colour = "grey40",
  pattern_fill = "grey40",

  pattern_density = 0.01,
  pattern_spacing = 0.05,
  pattern_size = 0.15,

  show.legend = FALSE
)
    }
  }
  
  p <- p + scale_fill_viridis_c(
      name = "AAT\nprevalence",
      na.value = "grey90",
      direction = 1,
      option = "viridis",
      limits = c(0, 0.75),
      oob = scales::squish,
      breaks = c(0, 0.25, 0.50, 0.75),
      trans = "identity",  # Square root transformation makes medium values more prominent
      labels = scales::percent_format(accuracy = 0.1)
    ) +
    # Add scale bar and north arrow
    annotation_scale(location = "bl", width_hint = 0.3, text_cex = 0.8, 
                    bar_cols = c("black", "white"), line_width = 1) +
    annotation_north_arrow(location = "bl", which_north = "true", 
                          pad_x = unit(0.3, "in"), pad_y = unit(0.3, "in"),
                          style = north_arrow_fancy_orienteering(text_size = 8)) +
    theme_void()
  
  p <- p +
    labs(
      title = paste("AAT prevalence by district in Ethiopia", title_suffix)
    ) +
    theme(
      plot.title = element_text(hjust = 0.5, size = 26, face = "bold"),
      plot.subtitle = element_text(hjust = 0.5, size = 11),
      plot.caption = element_text(hjust = 0.5, size = 9, color = "grey60"),
      legend.position = "right",
      legend.key.height = unit(1.5, "cm"),
      legend.key.width = unit(0.5, "cm")
    )
  
  # Add uncertainty caption if high uncertainty areas exist (like Nigerian version)
  if(show_uncertainty && "high_uncertainty" %in% names(ethiopia_zones_final) && 
     any(ethiopia_zones_final$high_uncertainty, na.rm = TRUE)) {
    p <- p + labs(caption = "Cross-hatched areas indicate high uncertainty (95% CI width > 0.80)")
  }
  
  p <- p + geom_sf(data = boundary_display$main_dashed,
                   color = "black", linetype = "dashed", lwd = 0.55,
                   lineend = "butt", inherit.aes = FALSE, show.legend = FALSE)
  p <- add_disputed_boundary_caption(p)

  # Add bovine data points if requested and available (for percentile maps)
  if(add_bovine && !is.null(bovine_ethiopia_sf) && nrow(bovine_ethiopia_sf) > 0) {
    p <- p + geom_point(data = st_drop_geometry(bovine_ethiopia_sf), 
                       aes(x = lon, y = lat, size = Number_of_animal_tested, shape = Test_Type), colour="black", fill="white", stroke=0.8,
                       alpha = 0.8)  # Increased alpha for better visibility
    
    # Add additional scales for bovine data
    p <- p +
      # Add size legend for sample size
      scale_size_continuous(name = "Sample size", 
                           range = c(1, 10),  # Increased from c(1, 4) to make sizes more distinguishable
                           breaks = c(10, 50, 100, 200),
                           labels = c("10", "50", "100", "200+")) +
      # Add color scale for test types
      scale_color_manual(name = "Test type",
                        values = c("HCT/BCT" = "#00FFFF", "PCR" = "#FF6347"),
                        guide = guide_legend(override.aes = list(size = 3, alpha = 0.8))) +
                        scale_shape_manual(values = c("HCT/BCT" = 21, "PCR" = 22))
  }
  
  # Add inset map if requested and data is available
  if(add_inset && !is.null(africa_countries_sf) && !is.null(ethiopia_country_sf)) {
    # Create inset map showing Ethiopia's location in Africa
    inset_plot <- ggplot() +
      geom_sf(data = africa_countries_sf, fill = "grey90", color = NA) +
      geom_sf(data = ethiopia_country_sf, fill = "#440154", color = NA) +
      geom_sf(data = boundary_display$africa, color = "grey55", lwd = 0.12,
              inherit.aes = FALSE) +
      geom_sf(data = boundary_display$ethiopia, color = "grey30", lwd = 0.2,
              inherit.aes = FALSE) +
      geom_sf(data = boundary_display$africa_dashed, color = "grey25",
              linetype = "dashed", lwd = 0.2, lineend = "butt",
              inherit.aes = FALSE, show.legend = FALSE) +
      theme_void() +
      theme(
        panel.background = element_rect(fill = "white", color = "black", size = 0.5),
        plot.margin = margin(2.1, 2.1, 2.1, 2.1)
      ) +
      coord_sf(expand = FALSE)
    
    # Reserve a separate side column: the inset cannot overlap map legends.
    legend <- cowplot::get_legend(p + theme(
      legend.key.height = unit(0.6, "cm"),
      legend.spacing.y = unit(0.15, "cm"),
      legend.margin = margin(2, 2, 2, 2),
      legend.box.margin = margin(0, 0, 0, 0)
    ))
    title_text <- p$labels$title
    caption_text <- p$labels$caption
    map_only <- p + theme(legend.position = "none") +
      labs(title = NULL, caption = NULL)
    sidebar <- cowplot::plot_grid(inset_plot, legend, ncol = 1,
                                   rel_heights = c(0.25, 0.75))
    body <- cowplot::plot_grid(map_only, sidebar, nrow = 1,
                                rel_widths = c(0.80, 0.20))
    title_row <- cowplot::ggdraw() + cowplot::draw_label(
      title_text, fontface = "bold", size = 20, x = 0.5, hjust = 0.5)
    caption_row <- cowplot::ggdraw() + cowplot::draw_label(
      caption_text, size = 8, color = "grey50", x = 0.5, hjust = 0.5)
    p <- cowplot::plot_grid(title_row, body, caption_row, ncol = 1,
                             rel_heights = c(0.065, 0.85, 0.085))
  }
  
  return(p)
}

